# Demo1: (5,6)=1, r+c=11 >10 -> RIGHT
#   Output: (4,8)=1, (5,6)=1, fills (5,7),(5,8)
# Above: (r-1, c+2) = (4,8) ✓ - shifts right!
# Right: (r, c) = (5,6) ✓ = stays at original
# Fill: (r, c+1), (r, c+2) = (5,7), (5,8) ✓

# The pattern is:
# V=1 at (r,c):
# If r+c <= threshold (LEFT):
#   Above: (r-1, c) - no shift
#   Left: (r, c-2) - shifts -2
#   Fill: (r, c-1) to (r, c) - between left and original
# If r+c > threshold (RIGHT):
#   Above: (r-1, c+2) - shifts +2
#   Right: (r, c) - no shift
#   Fill: (r, c+1) to (r, c+2) - between original and shifted right

def process(v, r, c):
    h, w = 10, 10
    threshold = 10
    output = [[0] * w for _ in range(h)]

    if v == 1:
        if r + c <= threshold:
            # LEFT: shift left horizontally
            out1 = (r - 1, c)
            out2 = (r, c - 2)
            fill_start = c - 1
            fill_end = c
        else:
            # RIGHT: shift right, original stays
            out1 = (r - 1, c + 2)
            out2 = (r, c)
            fill_start = c + 1
            fill_end = c + 2

        # Write outputs
        for ar, ac in [out1]:
            if 0 <= ar < h and 0 <= ac < w:
                output[ar][ac] = 1
        for ar, ac in [out2]:
            if 0 <= ar < h and 0 <= ac < w:
                output[ar][ac] = 1
        # Fill
        for fc in range(fill_start, fill_end + 1):
            if 0 <= fc < w:
                output[r][fc] = 5
    else:
        if r < c:
            # VERT
            output[r][c] = v
            if r + v < h:
                output[r+v][c] = v
            for i in range(1, v):
                if r + i < h:
                    output[r+i][c] = 5
        else:
            # HORIZ
            output[r][c] = v
            fill_len = 2 * v
            for fc in range(c - fill_len, c):
                if 0 <= fc < w:
                    output[r][fc] = 5
            if c - fill_len >= 0:
                output[r][c - fill_len] = v

