        if c <= threshold_col:
            # LEFT: (r-1, c), (r, c-2), fills (r, c-1) to (r, c)
            if r-1 >= 0 and 0 <= c < w:
                out[r-1][c] = 1
            if r >= 0 and 0 <= c-2 < w:
                out[r][c-2] = 1
            if r >= 0 and r < h and c-1 >= 0 and c < w:
                out[r][c-1] = 5
            if r >= 0 and r < h and 0 <= c < w:
                out[r][c] = 5
        else:
            # RIGHT: (r-1, c+2), (r, c), fills (r, c+1) to (r, c+2)
            if r-1 >= 0 and 0 <= c+2 < w:
                out[r-1][c+2] = 1
            if r >= 0 and 0 <= c < w:
                out[r][c] = 1
            if r >= 0 and r < h and 0 <= c+1 < w:
                out[r][c+1] = 5
            if r >= 0 and r < h and 0 <= c+2 < w:
                out[r][c+2] = 5
    else:
